-- ON filegroup / partition scheme(column) and FILESTREAM_ON on tables, indexes and constraints
CREATE TABLE t (a int, b varbinary(max) FILESTREAM, g uniqueidentifier ROWGUIDCOL UNIQUE) ON ps(a) FILESTREAM_ON fsps;
CREATE TABLE t (a int, CONSTRAINT pk PRIMARY KEY (a) ON [PRIMARY], INDEX ix (a) ON fg2);
CREATE TABLE t (a int CONSTRAINT pk PRIMARY KEY ON ps(a));
CREATE UNIQUE INDEX ix ON t (a) ON ps(a);
CREATE INDEX ix ON t (a) ON [PRIMARY] FILESTREAM_ON fs;
CREATE CLUSTERED COLUMNSTORE INDEX cci ON t ON ps(a);
ALTER TABLE t ADD CONSTRAINT pk PRIMARY KEY CLUSTERED (a) ON ps(a);
CREATE PRIMARY XML INDEX px ON t (x);
CREATE TABLE t (a int CONSTRAINT pk PRIMARY KEY WITH (FILLFACTOR = 80) ON [PRIMARY], b int UNIQUE NONCLUSTERED);
